// Replay test for batch256 — linkComputer.ts.
// Truth generated by tool/ts2dart/_batch256_truth.cjs (real recursive TS transpile).
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import '../lib/src/monaco/base/common/charCode.dart';
import '../lib/src/monaco/editor/common/languages/linkComputer.dart';

Map<String, dynamic> _loadTruth() => jsonDecode(
      File('tool/ts2dart/batch256_truth.json').readAsStringSync(),
    ) as Map<String, dynamic>;

class _Target implements ILinkComputerTarget {
  final List<String> lines;
  _Target(this.lines);

  @override
  int getLineCount() => lines.length;

  @override
  String getLineContent(int lineNumber) => lines[lineNumber - 1];
}

Map<String, dynamic> _projectLink(ILink link) => {
      'range': {
        'startLineNumber': link.range.startLineNumber,
        'startColumn': link.range.startColumn,
        'endLineNumber': link.range.endLineNumber,
        'endColumn': link.range.endColumn,
      },
      'url': link.url,
    };

List<Map<String, dynamic>> _projectLinks(List<ILink> links) =>
    links.map(_projectLink).toList();

bool _same(dynamic a, dynamic b) {
  if (a is Map && b is Map) {
    if (a.length != b.length) return false;
    for (final key in a.keys) {
      if (!b.containsKey(key) || !_same(a[key], b[key])) return false;
    }
    return true;
  }
  if (a is List && b is List) {
    if (a.length != b.length) return false;
    for (int i = 0; i < a.length; i++) {
      if (!_same(a[i], b[i])) return false;
    }
    return true;
  }
  return a == b;
}

/// Rebuild the same custom state machine the truth harness injected.
StateMachine _customStateMachine() => StateMachine([
      Edge(State.Start, 'a'.codeUnitAt(0), State.H),
      Edge(State.H, 'b'.codeUnitAt(0), State.HT),
      Edge(State.HT, 'c'.codeUnitAt(0), State.HTT),
      Edge(State.HTT, CharCode.Colon, State.AfterColon),
      Edge(State.AfterColon, CharCode.Slash, State.AlmostThere),
      Edge(State.AlmostThere, CharCode.Slash, State.End),
    ]);

void main() {
  final truth = _loadTruth();

  group('batch256 linkComputer replay', () {
    test('State enum values match TS const enum', () {
      final stateEnum = (truth['stateEnum'] as Map).cast<String, dynamic>();
      expect(State.Invalid, stateEnum['Invalid']);
      expect(State.Start, stateEnum['Start']);
      expect(State.H, stateEnum['H']);
      expect(State.HT, stateEnum['HT']);
      expect(State.HTT, stateEnum['HTT']);
      expect(State.HTTP, stateEnum['HTTP']);
      expect(State.F, stateEnum['F']);
      expect(State.FI, stateEnum['FI']);
      expect(State.FIL, stateEnum['FIL']);
      expect(State.BeforeColon, stateEnum['BeforeColon']);
      expect(State.AfterColon, stateEnum['AfterColon']);
      expect(State.AlmostThere, stateEnum['AlmostThere']);
      expect(State.End, stateEnum['End']);
      expect(State.Accept, stateEnum['Accept']);
      expect(State.LastKnownState, stateEnum['LastKnownState']);
    });

    test('all source-test assertLink cases', () {
      final cases = (truth['linkCases'] as List).cast<Map<String, dynamic>>();
      for (final c in cases) {
        final label = c['label'] as String;
        final text = c['text'] as String;
        final actual = _projectLinks(computeLinks(_Target([text])));
        final expected = (c['actual'] as List); // TS truth output (== upstream expectation)
        expect(actual.length, expected.length, reason: '[$label] link count');
        for (int i = 0; i < expected.length; i++) {
          expect(_same(actual[i], expected[i]), isTrue,
              reason: '[$label] link[$i]: got ${actual[i]} want ${expected[i]}');
        }
        // Also verify the upstream marker-derived expectation is identical to TS output.
        final upstream = (c['expected'] as List);
        expect(_same(upstream, expected), isTrue,
            reason: '[$label] upstream expectation != TS truth');
      }
    });

    test('null + unknown-caller guards', () {
      final cases = (truth['nullCases'] as List).cast<Map<String, dynamic>>();
      for (final c in cases) {
        final label = c['label'] as String;
        final result = label == 'null-model'
            ? _projectLinks(computeLinks(null))
            : _projectLinks(computeLinks(<String, dynamic>{})); // {} lacks target methods
        expect(result.isEmpty, isTrue, reason: '[$label] should be empty');
      }
    });

    test('multi-line model', () {
      final c = (truth['multiLineCase'] as Map).cast<String, dynamic>();
      final lines = (c['lines'] as List).cast<String>();
      final actual = _projectLinks(computeLinks(_Target(lines)));
      final expected = (c['actual'] as List);
      expect(actual.length, expected.length, reason: 'multiLine link count');
      for (int i = 0; i < expected.length; i++) {
        expect(_same(actual[i], expected[i]), isTrue,
            reason: 'multiLine link[$i]: got ${actual[i]} want ${expected[i]}');
      }
    });

    test('custom state machine injection', () {
      final cases = (truth['customCases'] as List).cast<Map<String, dynamic>>();
      final sm = _customStateMachine();
      for (final c in cases) {
        final label = c['label'] as String;
        final text = c['text'] as String;
        final target = _Target([text]);
        final List<Map<String, dynamic>> actual;
        if (label == 'custom-default-machine-ignores-abc') {
          actual = _projectLinks(computeLinks(target));
        } else {
          actual = _projectLinks(LinkComputer.computeLinks(target, sm));
        }
        final expected = (c['actual'] as List);
        expect(actual.length, expected.length, reason: '[$label] link count');
        for (int i = 0; i < expected.length; i++) {
          expect(_same(actual[i], expected[i]), isTrue,
              reason: '[$label] link[$i]: got ${actual[i]} want ${expected[i]}');
        }
      }
    });

    test('StateMachine.nextState probes', () {
      final probes = (truth['smProbes'] as List).cast<Map<String, dynamic>>();
      final sm = _customStateMachine();
      for (final p in probes) {
        final from = (p['from'] as num).toInt();
        final ch = (p['ch'] as num).toInt();
        expect(sm.nextState(from, ch), p['to'],
            reason: 'nextState($from, $ch)');
      }
    });
  });
}
